-- Retry pattern for deadlock victims
DECLARE @retry INT = 3;
WHILE @retry > 0
BEGIN
    BEGIN TRY
        BEGIN TRAN;
        UPDATE dbo.Accounts SET Balance -= 100 WHERE Id = 1;
        UPDATE dbo.Accounts SET Balance += 100 WHERE Id = 2;
        COMMIT;
        BREAK;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK;
        IF ERROR_NUMBER() = 1205 AND @retry > 1
            BEGIN SET @retry -= 1; WAITFOR DELAY '00:00:00.200'; END
        ELSE THROW;
    END CATCH;
END;
